package com.ailab.system.report.provider;
import com.ailab.system.report.config.*; import com.ailab.system.report.model.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public final class AssetSummaryProvider extends AbstractLabDataSourceProvider { public AssetSummaryProvider(){super(ReportConfigCatalog.ASSET_SUMMARY,new LinkedHashSet<String>(Arrays.asList("period","bizLine","owner","ownerId","assetStage","assetType")));} protected ReportSectionData loadValidated(ReportQueryCriteria c,ReportSectionConfig s){List<Map<String,Object>>r=copyRows(mapper().selectAssets(c));int risk=0;for(Map<String,Object>x:r)if(Boolean.TRUE.equals(x.get("singlePointRisk")))risk++;Map<String,Object>z=summaryCount(r);z.put("singlePointRiskCount",risk);return section(c,s,r,z);}}
